$function$

CREATE OR REPLACE FUNCTION financial_core.lock_financial_occurrence(p_group_id uuid, p_source_module text, p_source_record_id text, p_effect_kind text, p_ledger_epoch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF p_group_id IS NULL OR p_source_module IS NULL OR p_source_record_id IS NULL
     OR p_effect_kind IS NULL OR p_ledger_epoch_id IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_OCCURRENCE_LOCK_KEY_REQUIRED' USING ERRCODE = '22004';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.jsonb_build_array(
        p_group_id, p_source_module, p_source_record_id,
        p_effect_kind, p_ledger_epoch_id
      )::text,
      0
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION financial_core.post_f3_command(p_command jsonb, p_opening jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid; v_group uuid; v_request uuid; v_action text; v_effect text; v_class public.financial_event_class;
  v_module text; v_source text; v_provenance uuid; v_account uuid; v_destination uuid;
  v_fund uuid; v_category uuid; v_member uuid; v_project uuid; v_occurred timestamptz;
  v_code text; v_amount text; v_numeric numeric; v_epoch public.financial_ledger_epochs%ROWTYPE;
  v_acc public.financial_accounts%ROWTYPE; v_dest public.financial_accounts%ROWTYPE;
  v_fund_row public.financial_funds%ROWTYPE; v_cat public.financial_categories%ROWTYPE;
  v_existing public.financial_events%ROWTYPE; v_existing_payload jsonb; v_payload jsonb;
  v_request_event uuid; v_source_event uuid; v_event uuid; v_hash text; v_key text; v_item jsonb;
  v_metadata jsonb; v_count integer; v_first public.financial_control_class;
  v_second public.financial_control_class; v_first_amount numeric; v_second_amount numeric;
  v_first_account uuid; v_second_account uuid; v_first_category uuid; v_second_category uuid;
BEGIN
  -- Authorization precedes all historical/conflict/target disclosure.
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'DENY' USING ERRCODE = '42501'; END IF;
  v_group := financial_core.f3_uuid(p_command->'group_id');
  BEGIN
    v_actor := financial_core.assert_finances_manage(v_group);
  EXCEPTION WHEN insufficient_privilege THEN RAISE EXCEPTION 'DENY' USING ERRCODE = '42501';
  END;
  IF pg_catalog.jsonb_typeof(p_command) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  FOR v_key IN SELECT pg_catalog.jsonb_object_keys(p_command) LOOP
    IF NOT (v_key = ANY(ARRAY['action','group_id','request_id','occurred_at','amount','currency',
      'account_id','destination_account_id','fund_id','category_id','member_id','project_id',
      'description','reference_metadata']))
    THEN RAISE EXCEPTION 'UNSUPPORTED_FIELD'; END IF;
  END LOOP;
  v_action := p_command->>'action';
  IF pg_catalog.jsonb_typeof(p_command->'action') IS DISTINCT FROM 'string'
    OR v_action NOT IN ('money_in','money_out','transfer','opening')
  THEN RAISE EXCEPTION 'EFFECT_NOT_ALLOWED'; END IF;
  v_class := CASE v_action WHEN 'opening' THEN 'opening_adjustment' ELSE v_action END;
  v_effect := CASE v_action WHEN 'money_in' THEN 'manual_income' WHEN 'money_out' THEN 'manual_expense'
    WHEN 'transfer' THEN 'account_transfer' ELSE 'opening_custody' END;
  IF v_action = 'opening' THEN
    IF p_opening IS NULL THEN RAISE EXCEPTION 'PRIVATE_EFFECT'; END IF;
    IF COALESCE(p_command->'request_id','null'::jsonb) <> 'null'::jsonb THEN RAISE EXCEPTION 'FIELD_PROHIBITED'; END IF;
    IF COALESCE(p_opening->'provenance','null'::jsonb) = 'null'::jsonb
    THEN RAISE EXCEPTION 'OPENING_PROVENANCE_REQUIRED'; END IF;
    IF financial_core.f3_uuid(p_opening->'group_id') <> v_group
      OR financial_core.f3_uuid(p_opening->'provenance'->'group_id') <> v_group
    THEN RAISE EXCEPTION 'CROSS_GROUP_SOURCE'; END IF;
    v_source := financial_core.f3_uuid(p_opening->'occurrence_id')::text;
    v_provenance := financial_core.f3_uuid(p_opening->'provenance'->'id');
    v_module := 'opening_finance';
  ELSE
    IF p_opening IS NOT NULL THEN RAISE EXCEPTION 'SOURCE_NOT_ALLOWED'; END IF;
    IF COALESCE(p_command->'request_id','null'::jsonb) = 'null'::jsonb THEN RAISE EXCEPTION 'REQUEST_ID_REQUIRED'; END IF;
    v_request := financial_core.f3_uuid(p_command->'request_id');
    v_source := v_request::text; v_module := 'manual_finance';
  END IF;
  PERFORM financial_core.lock_f3_identity(v_group,v_request,v_module,v_source,v_effect);
  -- Recheck after waits. Hold the membership row through transaction completion.
  PERFORM 1 FROM public.memberships m WHERE m.group_id=v_group AND m.user_id=v_actor FOR SHARE;
  BEGIN
    PERFORM financial_core.assert_finances_manage(v_group);
  EXCEPTION WHEN insufficient_privilege THEN RAISE EXCEPTION 'DENY' USING ERRCODE = '42501';
  END;
  SELECT e.id INTO v_request_event FROM public.financial_events e
    WHERE e.group_id=v_group AND e.request_id=v_request;
  SELECT e.id INTO v_source_event FROM public.financial_events e
    WHERE e.group_id=v_group AND e.source_module=v_module AND e.source_record_id=v_source AND e.effect_kind=v_effect;
  IF v_request_event IS NOT NULL AND v_source_event IS NOT NULL AND v_request_event<>v_source_event
  THEN RAISE EXCEPTION 'OCCURRENCE_INTEGRITY'; END IF;
  SELECT e.* INTO v_existing FROM public.financial_events e WHERE e.id=COALESCE(v_request_event,v_source_event);

  IF COALESCE(p_command->'description','null'::jsonb) <> 'null'::jsonb
    AND pg_catalog.jsonb_typeof(p_command->'description') <> 'string'
  THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
  v_metadata := COALESCE(NULLIF(p_command->'reference_metadata','null'::jsonb),'{}'::jsonb);
  IF pg_catalog.jsonb_typeof(v_metadata) <> 'object' THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_object_keys(v_metadata) k WHERE k NOT IN ('reference','evidence_ids'))
  THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
  IF COALESCE(v_metadata->'reference','null'::jsonb) <> 'null'::jsonb
    AND pg_catalog.jsonb_typeof(v_metadata->'reference') <> 'string'
  THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
  IF COALESCE(v_metadata->'evidence_ids','null'::jsonb) <> 'null'::jsonb THEN
    IF pg_catalog.jsonb_typeof(v_metadata->'evidence_ids') <> 'array' THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
    FOR v_item IN SELECT pg_catalog.jsonb_array_elements(v_metadata->'evidence_ids') LOOP
      PERFORM financial_core.f3_uuid(v_item);
    END LOOP;
  END IF;
  v_account := financial_core.f3_uuid(p_command->'account_id');
  v_occurred := financial_core.f3_timestamp(p_command->'occurred_at');
  v_destination := financial_core.f3_uuid(p_command->'destination_account_id',true);
  v_fund := financial_core.f3_uuid(p_command->'fund_id',true);
  v_category := financial_core.f3_uuid(p_command->'category_id',true);
  v_member := financial_core.f3_uuid(p_command->'member_id',true);
  v_project := financial_core.f3_uuid(p_command->'project_id',true);
  IF v_action='transfer' THEN
    IF v_destination IS NULL THEN RAISE EXCEPTION 'DESTINATION_REQUIRED'; END IF;
    IF v_account=v_destination THEN RAISE EXCEPTION 'SAME_ACCOUNT'; END IF;
  ELSIF v_destination IS NOT NULL THEN RAISE EXCEPTION 'FIELD_PROHIBITED';
  END IF;
  IF v_action IN ('money_in','money_out') THEN
    IF v_category IS NULL THEN RAISE EXCEPTION 'CATEGORY_REQUIRED'; END IF;
  ELSE
    IF v_category IS NOT NULL THEN RAISE EXCEPTION 'CATEGORY_PROHIBITED'; END IF;
    IF v_member IS NOT NULL OR v_project IS NOT NULL THEN RAISE EXCEPTION 'ATTRIBUTION_PROHIBITED'; END IF;
    IF v_fund IS NULL THEN RAISE EXCEPTION 'FUND_REQUIRED'; END IF;
  END IF;

  IF v_existing.id IS NOT NULL THEN
    SELECT c.canonical_payload INTO v_existing_payload
      FROM financial_core.posting_command_payloads c WHERE c.event_id=v_existing.id;
    IF v_existing_payload IS NULL OR v_existing_payload->>'contract_version' <> 'f3-posting-v1'
      OR financial_core.f3_fingerprint(v_existing_payload) <> v_existing.economic_payload_fingerprint
    THEN RAISE EXCEPTION 'OCCURRENCE_INTEGRITY'; END IF;
    v_epoch.id := v_existing.ledger_epoch_id;
    v_code := CASE WHEN COALESCE(p_command->'currency','null'::jsonb) = 'null'::jsonb
      THEN v_existing.currency ELSE financial_core.f3_currency(p_command->'currency') END;
    v_fund := COALESCE(v_fund,(v_existing_payload->>'fund_id')::uuid);
  ELSE
    -- Group lock is shared with the existing currency-transition boundary.
    PERFORM 1 FROM public.groups g WHERE g.id=v_group FOR SHARE;
    -- Stable UUID ordering for both custody accounts.
    PERFORM 1 FROM public.financial_accounts a WHERE a.id IN (v_account,v_destination) ORDER BY a.id FOR SHARE;
    SELECT a.* INTO v_acc FROM public.financial_accounts a WHERE a.id=v_account;
    IF v_acc.id IS NULL THEN RAISE EXCEPTION 'ACCOUNT_NOT_FOUND'; END IF;
    IF v_acc.group_id<>v_group THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
    IF v_acc.status<>'active' THEN RAISE EXCEPTION 'ACCOUNT_INACTIVE'; END IF;
    v_code := v_acc.currency;
    IF COALESCE(p_command->'currency','null'::jsonb) <> 'null'::jsonb
      AND financial_core.f3_currency(p_command->'currency')<>v_code THEN RAISE EXCEPTION 'CURRENCY_MISMATCH'; END IF;
    SELECT pg_catalog.count(*) INTO v_count FROM public.financial_ledger_epochs e
      WHERE e.group_id=v_group AND e.effective_from<=v_occurred AND (e.effective_to IS NULL OR v_occurred<e.effective_to);
    IF v_count=0 THEN RAISE EXCEPTION 'EPOCH_NOT_FOUND'; END IF;
    IF v_count<>1 THEN RAISE EXCEPTION 'EPOCH_AMBIGUOUS'; END IF;
    SELECT e.* INTO v_epoch FROM public.financial_ledger_epochs e
      WHERE e.group_id=v_group AND e.effective_from<=v_occurred AND (e.effective_to IS NULL OR v_occurred<e.effective_to) FOR SHARE;
    IF v_epoch.id IS NULL THEN RAISE EXCEPTION 'EPOCH_NOT_FOUND'; END IF;
    IF v_epoch.currency<>v_code THEN RAISE EXCEPTION 'EPOCH_CURRENCY_MISMATCH'; END IF;
    IF v_acc.opened_at>v_occurred OR NOT EXISTS (
      SELECT 1 FROM public.financial_ledger_epochs e WHERE e.id=v_acc.opened_ledger_epoch_id
        AND e.group_id=v_group AND e.currency=v_code AND e.effective_from<=v_occurred
    ) THEN RAISE EXCEPTION 'ACCOUNT_EPOCH_INCOMPATIBLE'; END IF;
    IF v_destination IS NOT NULL THEN
      SELECT a.* INTO v_dest FROM public.financial_accounts a WHERE a.id=v_destination;
      IF v_dest.id IS NULL THEN RAISE EXCEPTION 'ACCOUNT_NOT_FOUND'; END IF;
      IF v_dest.group_id<>v_group THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
      IF v_dest.status<>'active' THEN RAISE EXCEPTION 'ACCOUNT_INACTIVE'; END IF;
      IF v_dest.currency<>v_code THEN RAISE EXCEPTION 'CROSS_CURRENCY_TRANSFER'; END IF;
      IF v_dest.opened_at>v_occurred OR NOT EXISTS (
        SELECT 1 FROM public.financial_ledger_epochs e WHERE e.id=v_dest.opened_ledger_epoch_id
          AND e.group_id=v_group AND e.currency=v_code AND e.effective_from<=v_occurred
      ) THEN RAISE EXCEPTION 'ACCOUNT_EPOCH_INCOMPATIBLE'; END IF;
    END IF;
    IF v_fund IS NULL THEN
      SELECT f.* INTO v_fund_row FROM public.financial_funds f
        WHERE f.group_id=v_group AND f.is_default AND f.status='active' AND NOT f.is_restricted FOR SHARE;
      IF v_fund_row.id IS NULL THEN RAISE EXCEPTION 'DEFAULT_FUND_UNRESOLVED'; END IF;
      v_fund := v_fund_row.id;
    ELSE
      SELECT f.* INTO v_fund_row FROM public.financial_funds f WHERE f.id=v_fund FOR SHARE;
      IF v_fund_row.id IS NULL THEN RAISE EXCEPTION 'FUND_NOT_FOUND'; END IF;
      IF v_fund_row.group_id<>v_group THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
      IF v_fund_row.status<>'active' THEN RAISE EXCEPTION 'FUND_INACTIVE'; END IF;
    END IF;
    IF v_category IS NOT NULL THEN
      SELECT c.* INTO v_cat FROM public.financial_categories c WHERE c.id=v_category FOR SHARE;
      IF v_cat.id IS NULL THEN RAISE EXCEPTION 'CATEGORY_NOT_FOUND'; END IF;
      IF v_cat.group_id<>v_group THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
      IF v_cat.status<>'active' THEN RAISE EXCEPTION 'CATEGORY_INACTIVE'; END IF;
      IF v_cat.category_class::text <> (CASE v_action WHEN 'money_in' THEN 'income' ELSE 'expense' END)
      THEN RAISE EXCEPTION 'CATEGORY_CLASS_MISMATCH'; END IF;
    END IF;
    IF v_member IS NOT NULL THEN
      PERFORM 1 FROM public.memberships m WHERE m.id=v_member FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION 'MEMBER_NOT_FOUND'; END IF;
      IF NOT EXISTS (SELECT 1 FROM public.memberships m WHERE m.id=v_member AND m.group_id=v_group)
      THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
    END IF;
    IF v_project IS NOT NULL THEN
      PERFORM 1 FROM public.projects p WHERE p.id=v_project FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION 'PROJECT_NOT_FOUND'; END IF;
      IF NOT EXISTS (SELECT 1 FROM public.projects p WHERE p.id=v_project AND p.group_id=v_group)
      THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
    END IF;
    IF v_action='money_out' AND COALESCE(financial_core.f3_trim(p_command->>'description'),'')=''
    THEN RAISE EXCEPTION 'DESCRIPTION_REQUIRED'; END IF;
  END IF;
  v_amount := financial_core.f3_amount(p_command->'amount',v_code);
  v_payload := pg_catalog.jsonb_build_object(
    'contract_version','f3-posting-v1','group_id',v_group,'ledger_epoch_id',v_epoch.id,
    'event_class',v_class,'effect_kind',v_effect,'currency',v_code,'amount',v_amount,
    'occurred_at',pg_catalog.to_char(v_occurred AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'source_module',v_module,'source_record_id',v_source,'request_id',v_request,'account_id',v_account,
    'destination_account_id',v_destination,'fund_id',v_fund,'category_id',v_category,
    'member_id',v_member,'project_id',v_project,'opening_provenance_id',v_provenance);
  v_hash := financial_core.f3_fingerprint(v_payload);
  IF v_existing.id IS NOT NULL THEN
    IF financial_core.f3_canonical(v_payload) <> financial_core.f3_canonical(v_existing_payload)
    THEN RAISE EXCEPTION 'CONFLICT'; END IF;
    RETURN pg_catalog.jsonb_build_object('decision','IDEMPOTENT_RETURN_EXISTING','event_id',v_existing.id,
      'ledger_epoch_id',v_existing.ledger_epoch_id,'fingerprint',v_existing.economic_payload_fingerprint,
      'new_event_count',0,'new_posting_count',0);
  END IF;
  -- Revalidate after target/configuration lock waits as well.
  BEGIN
    PERFORM financial_core.assert_finances_manage(v_group);
  EXCEPTION WHEN insufficient_privilege THEN RAISE EXCEPTION 'DENY' USING ERRCODE = '42501';
  END;
  v_numeric := v_amount::numeric;
  CASE v_action
    WHEN 'money_in' THEN
      v_first:='custody'; v_first_amount:=v_numeric; v_first_account:=v_account;
      v_second:='income'; v_second_amount:=-v_numeric; v_second_category:=v_category;
    WHEN 'money_out' THEN
      v_first:='expense'; v_first_amount:=v_numeric; v_first_category:=v_category;
      v_second:='custody'; v_second_amount:=-v_numeric; v_second_account:=v_account;
    WHEN 'transfer' THEN
      v_first:='custody'; v_first_amount:=-v_numeric; v_first_account:=v_account;
      v_second:='custody'; v_second_amount:=v_numeric; v_second_account:=v_destination;
    WHEN 'opening' THEN
      v_first:='custody'; v_first_amount:=v_numeric; v_first_account:=v_account;
      v_second:='opening_position'; v_second_amount:=-v_numeric;
  END CASE;
  INSERT INTO public.financial_events(group_id,ledger_epoch_id,currency,event_class,source_module,
    source_record_id,effect_kind,request_id,economic_payload_fingerprint,occurred_at,created_by,description,reference_metadata,status)
  VALUES(v_group,v_epoch.id,v_code,v_class,v_module,v_source,v_effect,v_request,v_hash,v_occurred,v_actor,
    p_command->>'description',v_metadata,'posted') RETURNING id INTO v_event;
  INSERT INTO public.financial_postings(event_id,group_id,ledger_epoch_id,currency,occurred_at,
    amount_signed,control_class,account_id,fund_id,category_id,category_class,member_id,project_id)
  SELECT v_event,v_group,v_epoch.id,v_code,v_occurred,x.amount,x.control,x.account,v_fund,x.category,
    CASE WHEN x.category IS NOT NULL THEN x.control::text::public.financial_category_class END,v_member,v_project
  FROM (VALUES (v_first_amount,v_first,v_first_account,v_first_category),
    (v_second_amount,v_second,v_second_account,v_second_category)) AS x(amount,control,account,category);
  INSERT INTO financial_core.posting_command_payloads(event_id,canonical_payload) VALUES(v_event,v_payload);
  RETURN pg_catalog.jsonb_build_object('decision','POSTED','event_id',v_event,'ledger_epoch_id',v_epoch.id,
    'fingerprint',v_hash,'new_event_count',1,'new_posting_count',2);
END;
$function$

CREATE OR REPLACE FUNCTION financial_core.post_f3_opening_cash(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid;
  v_group uuid;
  v_occurrence uuid;
  v_provenance_id uuid;
  v_account_id uuid;
  v_fund_id uuid;
  v_provenance jsonb;
  v_metadata jsonb;
  v_description text;
  v_reference text;
  v_source_at timestamptz;
  v_evidence jsonb := '[]'::jsonb;
  v_item jsonb;
  v_key text;
  v_existing_event uuid;
  v_existing_provenance uuid;
  v_manual_event uuid;
  v_saved financial_core.opening_provenances%ROWTYPE;
  v_account public.financial_accounts%ROWTYPE;
  v_fund public.financial_funds%ROWTYPE;
  v_epoch_count integer;
  v_epoch public.financial_ledger_epochs%ROWTYPE;
  v_inner jsonb;
BEGIN
  -- Initial authorization precedes history, conflict, target and provenance lookup.
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'DENY' USING ERRCODE = '42501'; END IF;
  IF pg_catalog.jsonb_typeof(p_command) IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  v_group := financial_core.f3_uuid(p_command->'group_id');
  BEGIN
    v_actor := financial_core.assert_finances_manage(v_group);
  EXCEPTION WHEN insufficient_privilege THEN
    RAISE EXCEPTION 'DENY' USING ERRCODE = '42501';
  END;

  FOR v_key IN SELECT pg_catalog.jsonb_object_keys(p_command) LOOP
    IF NOT (v_key = ANY(ARRAY['group_id','opening_occurrence_id','opening_provenance_id',
      'account_id','fund_id','amount','occurred_at','currency','provenance']))
    THEN RAISE EXCEPTION 'UNSUPPORTED_FIELD'; END IF;
  END LOOP;
  IF p_command->'group_id' IS NULL OR p_command->'opening_occurrence_id' IS NULL
    OR p_command->'opening_provenance_id' IS NULL OR p_command->'account_id' IS NULL
    OR p_command->'fund_id' IS NULL OR p_command->'amount' IS NULL
    OR p_command->'occurred_at' IS NULL OR p_command->'provenance' IS NULL
    OR COALESCE(p_command->'currency','"ok"'::jsonb) = 'null'::jsonb
  THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;

  v_occurrence := financial_core.f3_uuid(p_command->'opening_occurrence_id');
  v_provenance_id := financial_core.f3_uuid(p_command->'opening_provenance_id');
  v_account_id := financial_core.f3_uuid(p_command->'account_id');
  v_fund_id := financial_core.f3_uuid(p_command->'fund_id');
  v_provenance := p_command->'provenance';
  IF pg_catalog.jsonb_typeof(v_provenance) IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  FOR v_key IN SELECT pg_catalog.jsonb_object_keys(v_provenance) LOOP
    IF v_key NOT IN ('source_description','source_at','reference_metadata')
    THEN RAISE EXCEPTION 'UNSUPPORTED_FIELD'; END IF;
  END LOOP;
  IF pg_catalog.jsonb_typeof(v_provenance->'source_description') IS DISTINCT FROM 'string'
  THEN RAISE EXCEPTION 'INVALID_PROVENANCE'; END IF;
  v_description := financial_core.f3_opening_safe_text(v_provenance->>'source_description',1000,true);
  IF COALESCE(v_provenance->'source_at','null'::jsonb) <> 'null'::jsonb THEN
    v_source_at := financial_core.f3_timestamp(v_provenance->'source_at');
  END IF;
  v_metadata := COALESCE(NULLIF(v_provenance->'reference_metadata','null'::jsonb),'{}'::jsonb);
  IF pg_catalog.jsonb_typeof(v_metadata) IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'INVALID_PROVENANCE'; END IF;
  FOR v_key IN SELECT pg_catalog.jsonb_object_keys(v_metadata) LOOP
    IF v_key NOT IN ('reference','evidence_ids') THEN RAISE EXCEPTION 'UNSUPPORTED_FIELD'; END IF;
  END LOOP;
  IF COALESCE(v_metadata->'reference','null'::jsonb) <> 'null'::jsonb THEN
    IF pg_catalog.jsonb_typeof(v_metadata->'reference') IS DISTINCT FROM 'string'
    THEN RAISE EXCEPTION 'INVALID_PROVENANCE'; END IF;
    v_reference := financial_core.f3_opening_safe_text(v_metadata->>'reference',500,false);
  END IF;
  IF COALESCE(v_metadata->'evidence_ids','null'::jsonb) <> 'null'::jsonb THEN
    IF pg_catalog.jsonb_typeof(v_metadata->'evidence_ids') IS DISTINCT FROM 'array'
      OR pg_catalog.jsonb_array_length(v_metadata->'evidence_ids') > 20
    THEN RAISE EXCEPTION 'INVALID_PROVENANCE'; END IF;
    FOR v_item IN SELECT pg_catalog.jsonb_array_elements(v_metadata->'evidence_ids') LOOP
      v_evidence := v_evidence || pg_catalog.jsonb_build_array(financial_core.f3_uuid(v_item));
    END LOOP;
  END IF;
  v_metadata := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'reference',v_reference,'evidence_ids',CASE
      WHEN v_metadata ? 'evidence_ids' AND v_metadata->'evidence_ids' <> 'null'::jsonb THEN v_evidence
      ELSE NULL END));

  -- Global order: immutable F3 source occurrence, then provenance identity.
  PERFORM financial_core.lock_f3_identity(v_group,NULL,'opening_finance',v_occurrence::text,'opening_custody');
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    pg_catalog.jsonb_build_array('f3-opening-provenance',v_provenance_id)::text,0));

  -- Hold and recheck current authorization after every advisory-lock wait.
  PERFORM 1 FROM public.memberships m
    WHERE m.group_id=v_group AND m.user_id=v_actor FOR SHARE;
  BEGIN
    PERFORM financial_core.assert_finances_manage(v_group);
  EXCEPTION WHEN insufficient_privilege THEN
    RAISE EXCEPTION 'DENY' USING ERRCODE = '42501';
  END;

  SELECT e.id INTO v_existing_event FROM public.financial_events e
    WHERE e.group_id=v_group AND e.source_module='opening_finance'
      AND e.source_record_id=v_occurrence::text AND e.effect_kind='opening_custody';
  IF v_existing_event IS NOT NULL THEN
    SELECT (c.canonical_payload->>'opening_provenance_id')::uuid
      INTO v_existing_provenance
      FROM financial_core.posting_command_payloads c
      WHERE c.event_id=v_existing_event;
    IF v_existing_provenance IS NULL THEN RAISE EXCEPTION 'PROVENANCE_INTEGRITY'; END IF;
  END IF;
  SELECT e.id INTO v_manual_event FROM public.financial_events e
    WHERE e.group_id=v_group AND e.request_id=v_occurrence;
  IF v_manual_event IS NOT NULL THEN RAISE EXCEPTION 'REQUEST_ID_REUSED'; END IF;

  SELECT p.* INTO v_saved FROM financial_core.opening_provenances p
    WHERE p.id=v_provenance_id;
  IF v_saved.id IS NOT NULL AND v_saved.group_id<>v_group
  THEN RAISE EXCEPTION 'DENY' USING ERRCODE = '42501'; END IF;

  v_inner := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'action','opening','group_id',v_group,'occurred_at',p_command->'occurred_at',
    'amount',p_command->'amount','currency',p_command->'currency',
    'account_id',v_account_id,'fund_id',v_fund_id,
    'description',CASE WHEN v_saved.id IS NULL THEN v_description ELSE v_saved.source_description END,
    'reference_metadata',CASE WHEN v_saved.id IS NULL THEN v_metadata ELSE v_saved.reference_metadata END));

  -- Existing occurrence replay/conflict uses frozen F3-02 payload before current catalog checks.
  IF v_existing_event IS NOT NULL THEN
    IF v_existing_provenance=v_provenance_id AND v_saved.id IS NULL
    THEN RAISE EXCEPTION 'PROVENANCE_INTEGRITY'; END IF;
    RETURN financial_core.post_f3_command(v_inner,pg_catalog.jsonb_build_object(
      'group_id',v_group,'occurrence_id',v_occurrence,
      'provenance',pg_catalog.jsonb_build_object('id',v_provenance_id,'group_id',v_group)));
  END IF;

  IF v_saved.id IS NULL THEN
    INSERT INTO financial_core.opening_provenances(
      id,group_id,source_description,source_at,reference_metadata,recorded_by)
    VALUES(v_provenance_id,v_group,v_description,v_source_at,v_metadata,v_actor)
    RETURNING * INTO v_saved;
  END IF;

  -- Lock configuration rows before the private engine resolves them again.
  SELECT a.* INTO v_account FROM public.financial_accounts a
    WHERE a.id=v_account_id AND a.group_id=v_group FOR SHARE;
  IF v_account.id IS NULL THEN RAISE EXCEPTION 'ACCOUNT_NOT_FOUND'; END IF;
  IF v_account.kind NOT IN ('bank','cash') THEN RAISE EXCEPTION 'ACCOUNT_KIND_NOT_ALLOWED'; END IF;
  IF v_account.status<>'active' OR v_account.closed_at IS NOT NULL
  THEN RAISE EXCEPTION 'ACCOUNT_INACTIVE'; END IF;

  SELECT f.* INTO v_fund FROM public.financial_funds f
    WHERE f.id=v_fund_id AND f.group_id=v_group FOR SHARE;
  IF v_fund.id IS NULL THEN RAISE EXCEPTION 'FUND_NOT_FOUND'; END IF;
  IF v_fund.status<>'active' THEN RAISE EXCEPTION 'FUND_INACTIVE'; END IF;

  SELECT pg_catalog.count(*) INTO v_epoch_count FROM public.financial_ledger_epochs e
    WHERE e.group_id=v_group
      AND financial_core.f3_timestamp(p_command->'occurred_at')>=e.effective_from
      AND (e.effective_to IS NULL OR financial_core.f3_timestamp(p_command->'occurred_at')<e.effective_to);
  IF v_epoch_count<>1 THEN
    RAISE EXCEPTION '%',CASE WHEN v_epoch_count=0 THEN 'EPOCH_NOT_FOUND' ELSE 'EPOCH_AMBIGUOUS' END;
  END IF;
  SELECT e.* INTO v_epoch FROM public.financial_ledger_epochs e
    WHERE e.group_id=v_group
      AND financial_core.f3_timestamp(p_command->'occurred_at')>=e.effective_from
      AND (e.effective_to IS NULL OR financial_core.f3_timestamp(p_command->'occurred_at')<e.effective_to)
    FOR SHARE;

  -- Use only the committed provenance snapshot for the event narrative.
  v_inner := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'action','opening','group_id',v_group,'occurred_at',p_command->'occurred_at',
    'amount',p_command->'amount','currency',p_command->'currency',
    'account_id',v_account_id,'fund_id',v_fund_id,
    'description',v_saved.source_description,'reference_metadata',v_saved.reference_metadata));
  RETURN financial_core.post_f3_command(v_inner,pg_catalog.jsonb_build_object(
    'group_id',v_group,'occurrence_id',v_occurrence,
    'provenance',pg_catalog.jsonb_build_object('id',v_provenance_id,'group_id',v_group)));
END;
$function$

CREATE OR REPLACE FUNCTION financial_core.resolve_f3_correction_replacement(d jsonb, target jsonb, replay boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e jsonb:=target->'economic'; k text; action text; code text; amount text; occurred timestamptz;
 g uuid:=(target->>'group_id')::uuid; target_epoch uuid:=(target->>'ledger_epoch_id')::uuid;
 epoch uuid; n int; account uuid; destination uuid; fund uuid; category uuid; member uuid; project uuid;
 a public.financial_accounts%ROWTYPE; f public.financial_funds%ROWTYPE;
 cat public.financial_categories%ROWTYPE; original jsonb:=target->'economic';
BEGIN
 IF pg_catalog.jsonb_typeof(d) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'REPLACEMENT_REQUIRED'; END IF;
 FOR k IN SELECT pg_catalog.jsonb_object_keys(d) LOOP
  IF NOT(k=ANY(ARRAY['action','amount','occurred_at','currency','account_id','destination_account_id',
   'fund_id','category_id','member_id','project_id','description','reference_metadata']))
  THEN RAISE EXCEPTION 'UNSUPPORTED_FIELD'; END IF;
 END LOOP;
 IF d?'description' AND d->'description'<>'null'::jsonb
   AND pg_catalog.jsonb_typeof(d->'description')<>'string' THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
 IF d?'reference_metadata' AND d->'reference_metadata'<>'null'::jsonb THEN
  IF pg_catalog.jsonb_typeof(d->'reference_metadata')<>'object' THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
  FOR k IN SELECT pg_catalog.jsonb_object_keys(d->'reference_metadata') LOOP
   IF k NOT IN('reference','evidence_ids') THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
  END LOOP;
  IF d->'reference_metadata'?'reference' AND d->'reference_metadata'->'reference'<>'null'::jsonb
   AND pg_catalog.jsonb_typeof(d->'reference_metadata'->'reference')<>'string'
   THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
  IF d->'reference_metadata'?'evidence_ids' AND d->'reference_metadata'->'evidence_ids'<>'null'::jsonb THEN
   IF pg_catalog.jsonb_typeof(d->'reference_metadata'->'evidence_ids')<>'array'
   THEN RAISE EXCEPTION 'INVALID_METADATA'; END IF;
   PERFORM financial_core.f3_uuid(x.value)
    FROM pg_catalog.jsonb_array_elements(d->'reference_metadata'->'evidence_ids') x;
  END IF;
 END IF;
 FOR k IN SELECT pg_catalog.unnest(ARRAY['action','amount','occurred_at','currency','account_id',
  'destination_account_id','fund_id','category_id','member_id','project_id']) LOOP
  IF d?k THEN e:=pg_catalog.jsonb_set(e,ARRAY[k],d->k); END IF;
 END LOOP;
 IF pg_catalog.jsonb_typeof(e->'action')<>'string' THEN RAISE EXCEPTION 'INVALID_ACTION'; END IF;
 action:=e->>'action';
 IF action NOT IN('money_in','money_out','transfer') THEN RAISE EXCEPTION 'INVALID_ACTION'; END IF;
 IF NOT replay AND action<>original->>'action' THEN RAISE EXCEPTION 'ACTION_CHANGE_PROHIBITED'; END IF;
 code:=financial_core.f3_currency(e->'currency');
 IF NOT replay AND code<>target->>'currency' THEN RAISE EXCEPTION 'CROSS_CURRENCY_REPLACEMENT'; END IF;
 amount:=financial_core.f3_amount(e->'amount',code); occurred:=financial_core.f3_timestamp(e->'occurred_at');
 account:=financial_core.f3_uuid(e->'account_id',true);
 destination:=financial_core.f3_uuid(e->'destination_account_id',true);
 fund:=financial_core.f3_uuid(e->'fund_id',true); category:=financial_core.f3_uuid(e->'category_id',true);
 member:=financial_core.f3_uuid(e->'member_id',true); project:=financial_core.f3_uuid(e->'project_id',true);
 IF account IS NULL THEN RAISE EXCEPTION 'ACCOUNT_REQUIRED'; END IF;
 IF fund IS NULL THEN RAISE EXCEPTION 'FUND_REQUIRED'; END IF;
 IF action='transfer' THEN
  IF destination IS NULL THEN RAISE EXCEPTION 'DESTINATION_REQUIRED'; END IF;
  IF destination=account THEN RAISE EXCEPTION 'SAME_ACCOUNT'; END IF;
  IF category IS NOT NULL THEN RAISE EXCEPTION 'CATEGORY_PROHIBITED'; END IF;
  IF member IS NOT NULL OR project IS NOT NULL THEN RAISE EXCEPTION 'ATTRIBUTION_PROHIBITED'; END IF;
 ELSE
  IF destination IS NOT NULL THEN RAISE EXCEPTION 'FIELD_PROHIBITED'; END IF;
  IF category IS NULL THEN RAISE EXCEPTION 'CATEGORY_REQUIRED'; END IF;
 END IF;
 IF NOT replay THEN
  SELECT pg_catalog.count(*) INTO n FROM public.financial_ledger_epochs x
   WHERE x.group_id=g AND x.effective_from<=occurred AND(x.effective_to IS NULL OR occurred<x.effective_to);
  IF n=0 THEN RAISE EXCEPTION 'EPOCH_NOT_FOUND'; END IF;
  IF n<>1 THEN RAISE EXCEPTION 'EPOCH_AMBIGUOUS'; END IF;
  SELECT x.id INTO epoch FROM public.financial_ledger_epochs x
   WHERE x.group_id=g AND x.effective_from<=occurred AND(x.effective_to IS NULL OR occurred<x.effective_to) FOR SHARE;
  IF epoch<>target_epoch THEN RAISE EXCEPTION 'CROSS_EPOCH_REPLACEMENT'; END IF;
  PERFORM 1 FROM public.financial_accounts x WHERE x.id IN(account,destination) ORDER BY x.id FOR SHARE;
  FOR k IN SELECT pg_catalog.unnest(ARRAY['account_id','destination_account_id']) LOOP
   IF (CASE k WHEN 'account_id' THEN account ELSE destination END) IS NULL THEN CONTINUE; END IF;
   SELECT x.* INTO a FROM public.financial_accounts x WHERE x.id=(CASE k WHEN 'account_id' THEN account ELSE destination END);
   IF a.id IS NULL THEN RAISE EXCEPTION 'ACCOUNT_NOT_FOUND'; END IF;
   IF a.group_id<>g THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
   IF a.currency<>target->>'currency' THEN RAISE EXCEPTION 'CROSS_CURRENCY_REPLACEMENT'; END IF;
   IF a.opened_at>occurred OR NOT EXISTS(SELECT 1 FROM public.financial_ledger_epochs oe
    WHERE oe.id=a.opened_ledger_epoch_id AND oe.group_id=g AND oe.currency=a.currency AND oe.effective_from<=occurred)
   THEN RAISE EXCEPTION 'ACCOUNT_EPOCH_INCOMPATIBLE'; END IF;
   IF a.status<>'active' AND (original->>k)::uuid IS DISTINCT FROM a.id THEN RAISE EXCEPTION 'ACCOUNT_INACTIVE'; END IF;
  END LOOP;
  SELECT x.* INTO f FROM public.financial_funds x WHERE x.id=fund FOR SHARE;
  IF f.id IS NULL THEN RAISE EXCEPTION 'FUND_NOT_FOUND'; END IF;
  IF f.group_id<>g THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
  IF f.status<>'active' AND (original->>'fund_id')::uuid IS DISTINCT FROM fund THEN RAISE EXCEPTION 'FUND_INACTIVE'; END IF;
  IF category IS NOT NULL THEN
   SELECT x.* INTO cat FROM public.financial_categories x WHERE x.id=category FOR SHARE;
   IF cat.id IS NULL THEN RAISE EXCEPTION 'CATEGORY_NOT_FOUND'; END IF;
   IF cat.group_id<>g THEN RAISE EXCEPTION 'CROSS_GROUP_DIMENSION'; END IF;
   IF cat.category_class::text<>(CASE action WHEN 'money_in' THEN 'income' ELSE 'expense' END)
   THEN RAISE EXCEPTION 'CATEGORY_CLASS_MISMATCH'; END IF;
   IF cat.status<>'active' AND (original->>'category_id')::uuid IS DISTINCT FROM category
   THEN RAISE EXCEPTION 'CATEGORY_INACTIVE'; END IF;
  END IF;
  IF member IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.memberships x WHERE x.id=member AND x.group_id=g)
   THEN RAISE EXCEPTION 'MEMBER_NOT_FOUND'; END IF;
  IF project IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.projects x WHERE x.id=project AND x.group_id=g)
   THEN RAISE EXCEPTION 'PROJECT_NOT_FOUND'; END IF;
 END IF;
 RETURN pg_catalog.jsonb_build_object('action',action,'amount',amount,
  'occurred_at',financial_core.f3_correction_timestamp(occurred),'currency',code,
  'account_id',account,'destination_account_id',destination,'fund_id',fund,'category_id',category,
  'member_id',member,'project_id',project);
END; $function$

CREATE OR REPLACE FUNCTION financial_private.guard_ledger_epoch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  group_currency text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'LEDGER_EPOCH_IMMUTABLE';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NOT EXISTS (
      SELECT 1 FROM financial_private.epoch_transitions x
      WHERE x.transaction_id = txid_current() AND x.group_id = OLD.group_id
    )
      OR (NEW.group_id, NEW.currency, NEW.effective_from, NEW.source_kind,
          NEW.source_reference, NEW.approval_note, NEW.created_by,
          NEW.approved_by, NEW.approved_at, NEW.created_at)
         IS DISTINCT FROM
         (OLD.group_id, OLD.currency, OLD.effective_from, OLD.source_kind,
          OLD.source_reference, OLD.approval_note, OLD.created_by,
          OLD.approved_by, OLD.approved_at, OLD.created_at)
      OR OLD.effective_to IS NOT NULL
      OR NEW.effective_to IS NULL
    THEN
      RAISE EXCEPTION 'LEDGER_EPOCH_IMMUTABLE';
    END IF;
  END IF;
  IF NEW.effective_to IS NULL THEN
    IF NEW.effective_from > clock_timestamp() THEN
      RAISE EXCEPTION 'FUTURE_LEDGER_EPOCH_NOT_ACTIVE';
    END IF;
    SELECT currency INTO group_currency FROM public.groups WHERE id = NEW.group_id;
    IF group_currency IS DISTINCT FROM NEW.currency
      AND NOT EXISTS (
        SELECT 1 FROM financial_private.epoch_transitions x
        WHERE x.transaction_id = txid_current() AND x.group_id = NEW.group_id
      )
    THEN
      RAISE EXCEPTION 'ACTIVE_LEDGER_CURRENCY_MISMATCH';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
